def _fit(past, hold, features, dt, times, curves, rates):
    from scipy.optimize import least_squares
    rate_weight = 1.0
    target = np.r_[curves.ravel(), rate_weight * rates]

    def project(params):
        taus = np.exp([params[0], params[0] + params[1]])
        curve, rate = _basis(taus, past, hold, features, dt, times)
        design = np.concatenate((curve.reshape(-1, 9), rate_weight * rate))
        weights = np.linalg.lstsq(design, target, rcond=None)[0]
        return (design @ weights - target, weights, taus)
    best = None
    bounds = (np.log([0.015, 1.015]), np.log([20.0, 250.0]))
    for fast, slow in ((0.15, 1.0), (0.4, 2.5), (0.8, 4.0), (1.5, 8.0)):
        fit = least_squares(lambda p: project(p)[0], np.log([fast, slow / fast]), bounds=bounds, max_nfev=100, ftol=1e-10, xtol=1e-10, gtol=1e-10)
        if best is None or fit.cost < best.cost:
            best = fit
    _, weights, taus = project(best.x)
    return (taus, weights)

def _activity(dataset, past, dt):
    if dataset['shear_banding_index'] > 0.5:
        return np.zeros(len(past))
    excess = np.maximum(np.abs(past) - dataset['crit_stress'], 0.0)
    return np.tanh(excess ** 2 @ dt)
